import sklearn
print("sklearn imported from:", sklearn.__file__)

from sklearn.feature_extraction.text import CountVectorizer, TfidfVectorizer
from sklearn.exceptions import NotFittedError

corpus = [
    'This is the first document.',
    'This is the second second document.',
    'And the third one.',
    'Is this the first document?',
]
vocabulary = ['and', 'document', 'first', 'is', 'one', 'second', 'the', 'third', 'this']

for cls in (CountVectorizer, TfidfVectorizer):
    vectorizer = cls(vocabulary=vocabulary)
    print("\n===", cls.__name__, "===")
    print("has vocabulary_ before:", hasattr(vectorizer, "vocabulary_"))
    try:
        names = vectorizer.get_feature_names()
        print("get_feature_names OK:", names)
    except NotFittedError as exc:
        print("get_feature_names raised NotFittedError:", exc)
    print("has vocabulary_ after:", hasattr(vectorizer, "vocabulary_"))
    try:
        X = vectorizer.transform(corpus)
        print("transform OK, shape:", X.shape)
    except NotFittedError as exc:
        print("transform raised NotFittedError:", exc)
    try:
        inv = vectorizer.inverse_transform(vectorizer.transform(corpus))
        print("inverse_transform OK:", inv[0])
    except NotFittedError as exc:
        print("inverse_transform raised NotFittedError:", exc)

# No vocabulary provided -> must still raise NotFittedError
for cls in (CountVectorizer, TfidfVectorizer):
    vectorizer = cls()
    for method in ("get_feature_names", "inverse_transform"):
        try:
            if method == "get_feature_names":
                vectorizer.get_feature_names()
            else:
                vectorizer.inverse_transform([[0, 1]])
            print("UNEXPECTED: %s.%s did not raise" % (cls.__name__, method))
        except NotFittedError:
            print("expected NotFittedError for %s.%s" % (cls.__name__, method))
